	if mmList.funcList != nil {
		return mmList.funcList(ctx, accountID, groupID, initiatorID, videoID)
	}
	mmList.t.Fatalf("Unexpected call to ChapterMock.List. %v %v %v %v %v", ctx, accountID, groupID, initiatorID, videoID)
